package br.uninter.baozistore.controller; import br.uninter.baozistore.model.*; import br.uninter.baozistore.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/pedidos") public class PedidoController{ private final PedidoRepository r; public PedidoController(PedidoRepository r){this.r=r;} @PostMapping public Pedido salvar(@RequestBody Pedido c){return r.save(c);} @GetMapping public List<Pedido> listar(){return r.findAll();} @GetMapping("/{id}") public Pedido buscar(@PathVariable Long id){return r.findById(id).orElse(null);} @DeleteMapping("/{id}") public void excluir(@PathVariable Long id){r.deleteById(id);} }